Ext._define('web.cms.file.Window', {
    extend: 'core.RestfulWindow',
    title: 'Novo documento',
    rest: 'web.cms.file.Restful',
    width: 500,

    _range: function (start, length) {
        return Array.from({ length: length }, function (v, k) {
            return start + k;
        });
    },

    _comboFor: function (cfg) {
        var defaulftCfg = {
            xtype: 'combo',
            triggerAction: 'all',
            mode: 'local',
            width: 100,
            allowBlank: true,
            margins: '0, 15, 0 0',
            store: new Ext.data.ArrayStore({
                fields: ['id', 'text'],
                data: cfg.storeData,
            }),
            valueField: 'id',
            displayField: 'text',
        };
        var combo = Ext.apply(defaulftCfg, cfg);

        return combo;
    },

    getMonths: function () {
        var months = this._range(1, 12);

        months = months.map(function (item) {
            return [item, item];
        })
        months.unshift(['', ''])
        return months
    },

    _getAttachmentField: function (cfg) {
        if (!this._attachmentField) {
            this._attachmentField = Ext._create('core.fields.FileUploadField', {
                fieldLabel: "Anexo",
                // allowBlank: false,
                name: "ged",
                value: cfg.values.ged,
                loadingOwner: this,
                width: 350,
                listeners: {
                    scope: this,
                    afterchange: function(input, instance) {
                        var filename = instance.file_path.split('/')[1];
                        this._getTitleField().setValue(filename);
                        this._getTitleField().focus();
                    }
                }
            });
        }
        return this._attachmentField;
    },

    _getTitleField: function (cfg) {
        if (!this._titleField) {
            this._titleField = Ext._create('Ext.form.TextField', {
                fieldLabel: "Nome",
                name: "title",
                allowBlank: false,
                // maxLength: 260,
                selectOnFocus: true,
                anchor: '99%',
            });
        }
        return this._titleField;
    },

    getFormPanel: function (cfg) {
        var state = JSON.parse(sessionStorage.getItem('cms-state'));
        if (!this._formPanel)
            this._formPanel = Ext._create('Ext.form.FormPanel', {
                border: false,
                frame: true,
                items: [
                    {
                        xtype: 'hidden',
                        name: 'posts',
                        value: state.post,
                    },
                    // {
                    //     xtype: 'textfield',
                    //     fieldLabel: 'Nome',
                    //     width: 350,
                    //     name: 'title',
                    // },
                    this._getAttachmentField(cfg),
                    this._getTitleField(cfg),
                    this._comboFor({
                        name: 'ref_month',
                        fieldLabel: 'Mês',
                        storeData: this.getMonths(),
                        value: cfg.values.ref_month,
                    }),
                    // {
                    //     xtype: 'ged-fileuploadfield',
                    //     fieldLabel: 'Arquivo',
                    //     name: 'ged',
                    // },
                    {
                        xtype: 'textfield',
                        fieldLabel: 'Posição',
                        name: 'position',
                        emptyText: '9999',
                    },
                    {
                        xtype: 'tk-datetimefield',
                        fieldLabel: 'Alterado em',
                        name: 'published_date'
                    }
                ],
            });

        return this._formPanel;
    },
});
